    for i in case_ids.len() {
        if case_ids[i] == ("" + id) {
            if case_expanded[i] == "yes" {
                case_expanded[i] = "no"
            } else {
                case_expanded[i] = "yes"
            }
            break
        }
    }
    rebuild_lines()
    ui.case_list.render()
    let idx = -1
    for i in case_ids.len() {
        if case_ids[i] == ("" + id) { idx = i; break }
    }
    let msg = "已选中 #" + "" + id
    if idx >= 0 && case_expanded[idx] == "yes" {
        msg = "已展开 #" + "" + id + "（再点一次可折叠）"
    } else if idx >= 0 {
        msg = "已折叠 #" + "" + id + "（点卡片可展开详情）"
    }
    ui.hint.set_text(msg)
}

